from typing import Dict, List, Tuple


class Gradebook:
    def __init__(self) -> None:
        # assignment_name -> {"weight": float, "kind": str}
        self._assignments: Dict[str, Dict[str, float | str]] = {}
        # student_name -> {assignment_name: grade}
        self._grades: Dict[str, Dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self._assignments[name] = {"weight": float(weight), "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        grade = float(grade)
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the 2.0-5.0 scale.")

        if student not in self._grades:
            self._grades[student] = {}
        self._grades[student][assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})

        # Collect quizzes and all assignment grades (defaulting unrecorded to 2.0)
        quizzes: List[Tuple[float, str]] = []
        for name, info in self._assignments.items():
            grade = student_grades.get(name, 2.0)
            if info["kind"] == "quiz":
                quizzes.append((grade, name))

        # Identify which quiz to drop if student has more than one quiz
        dropped_quiz_name = None
        if len(quizzes) > 1:
            # Sort to find the lowest quiz grade.
            # In case of tie, dropping any single lowest grade is sufficient.
            quizzes.sort(key=lambda item: item[0])
            dropped_quiz_name = quizzes[0][1]

        total_weighted_sum = 0.0
        total_weight = 0.0

        for name, info in self._assignments.items():
            if name == dropped_quiz_name:
                continue

            grade = student_grades.get(name, 2.0)
            weight = info["weight"]

            total_weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0.0:
            return 0.0

        return round(total_weighted_sum / total_weight, 2)
```

